  'Une symphonie de saveurs o&ugrave; chaque plat raconte une histoire&comma; sublim&eacute;e par une s&eacute;lection viticole d\'exception&period; Parcourez notre galerie&comma; d&eacute;couvrez nos vins et r&eacute;servez votre exp&eacute;rience&period;' => 'Eine Symphonie der Aromen&comma; bei der jedes Gericht eine Geschichte erz&auml;hlt&comma; abgerundet durch eine au&szlig;ergew&ouml;hnliche Weinauswahl&period; St&ouml;bern Sie in unserer Galerie&comma; entdecken Sie unsere Weine und buchen Sie Ihr Erlebnis&period;',
